package res

import "testing"

// Values generated by test_vectors/linux_rand_oracle.c with glibc srand/rand.
func TestLinuxRandMatchesSeededCStream(t *testing.T) {
	want := []uint32{663956063, 244433572, 1408600669, 1364268002, 406769501, 648013376, 127199536, 1505416569, 2093757299, 1404218740, 1054851991, 837550022, 604968571, 554509898, 2018186748, 1236817271}
	var r resCRand
	r.seed(0xabc)
	for i, w := range want {
		if got := r.next(); got != w {
			t.Fatalf("draw %d got %d want %d", i, got, w)
		}
	}
}

func TestSourceRandomWordSequence(t *testing.T) {
	resGlobalRand.seed(0xabc)
	words := []uint32{0, 0, 0, 123}
	Abc_InfoRandom(words, 3)
	want := []uint32{0xe19ba373, 0x286a3640, 0x10dfca5d, 123}
	for i, w := range want {
		if words[i] != w {
			t.Fatalf("word %d got %08x want %08x", i, words[i], w)
		}
	}
}
